参考代码（递归 DFS 洪水填充 + 周长统计）：

```cpp
#include <bits/stdc++.h>
using namespace std;

int a[205][205];
bool vis[205][205];
int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};
int n, m;
int perim;

// 递归 DFS 找整座岛屿，同时统计周长
void dfs(int r, int c) {
    vis[r][c] = true;
    for (int k = 0; k < 4; k++) {
        int nr = r + dx[k], nc = c + dy[k];
        if (nr < 1 || nr > n || nc < 1 || nc > m) { perim++; continue; }
        if (a[nr][nc] == 0) { perim++; continue; }
        if (!vis[nr][nc]) dfs(nr, nc);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            cin >> a[i][j];
    int x, y;
    cin >> x >> y;
    dfs(x, y);
    cout << perim << '\n';
    return 0;
}
```

**原理说明**：递归 DFS 从起始格子出发找整座岛屿，边遍历边统计周长：每格的邻格为海洋或越界则计入。注意 n,m ≤ 200，递归深度最大 4×10⁴，安全。复杂度 O(n×m)。

参考代码（递归 DFS 判环，parent 标记）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 50005;
vector<int> g[N];
bool vis[N];

// 递归 DFS 判环：遍历到已访问且非 parent 的顶点即有环
bool dfs(int u, int parent) {
    vis[u] = true;
    for (int v : g[u]) {
        if (!vis[v]) {
            if (dfs(v, u)) return true;
        } else if (v != parent) {
            return true;
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    bool ok = false;
    for (int i = 1; i <= n; i++) {
        if (!vis[i] && dfs(i, 0)) {
            ok = true;
            break;
        }
    }
    cout << (ok ? "Yes" : "No") << '\n';
    return 0;
}
```

**原理说明**：递归 DFS 遍历无向图，记录父顶点（parent）。若某条边指向已访问且非 parent 的顶点，则此边与遍历树路径构成环。注意图可能不连通，须遍历所有连通分量。n ≤ 5×10⁴，递归深度安全。复杂度 O(n+m)。

参考代码（多源 BFS）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int dist[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    memset(dist, -1, sizeof(dist));
    queue<int> q;
    for (int i = 0; i < k; i++) {
        int s;
        cin >> s;
        dist[s] = 0;
        q.push(s);
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        if (dist[i] == -1) {
            cout << -1 << '\n';
            return 0;
        }
        ans = max(ans, dist[i]);
    }
    cout << ans << '\n';
    return 0;
}
```

**原理说明**：多源 BFS——把 k 个初始感染村庄全部入队，同时逐层扩展。dist 记录每个村庄被感染的天数，答案即最大 dist。若有村庄 dist 仍为 -1 则不可达，输出 -1。复杂度 O(n+m)。

参考代码（两遍 BFS 求树的直径）：

```cpp
#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int dist[N];

int bfs(int start) {
    memset(dist, -1, sizeof(dist));
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    int far = start;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (dist[u] > dist[far]) far = u;
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return far;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int u = bfs(1);        // 第一遍：找离 1 最远的点
    bfs(u);                // 第二遍：u 到最远点的距离即答案
    int ans = 0;
    for (int i = 1; i <= n; i++)
        ans = max(ans, dist[i]);
    cout << ans << '\n';
    return 0;
}
```

**原理说明**：树的直径 = 树上最长路径。任取一点 BFS 找到最远点 u，u 必为直径一端点；再从 u BFS，最远距离即直径。两次 BFS 复杂度 O(n+m)。
